style.css:
@-moz-document domain("pinterest.com") {
body {
    background-color: #ffffff !important;
  }

  nav[role="navigation"] {
    background-color: #ffe0f0 !important;
  }

  nav svg,
  nav a,
  nav div {
    fill: #e38bb3 !important;
    color: #e38bb3 !important;
  }

  div[role="dialog"] button,
  div[role="dialog"] svg {
    background-color: #ffe0f0 !important;
    fill: #e38bb3 !important;
    color: #e38bb3 !important;
    border-radius: 8px !important;
  }

  div[data-test-id*="header"],
  div[data-test-id*="profile"],
  div[style*="border-radius:9999px"] {
    background-color: #ffe0f0 !important;
  }

  /* 저장 버튼 */
  button[data-test-id="SaveButton"],
  div[data-test-id="save-button"] {
    background-color: #f5c1d1 !important;
    border-color: #f5c1d1 !important;
    color: white !important;
    border-radius: 9999px !important;
  }

  /* 하트 아이콘 */
  svg[aria-label="Like"],
  path[d="M16 29.55l-1.45-1.32C7.4 21.36 2 16.28 2 10.5 2 6.36 5.36 3 9.5 3c2.54 0 4.91 1.19 6.5 3.09C17.59 4.19 20.04 3 22.5 3 26.64 3 30 6.36 30 10.5c0 5.78-5.4 10.86-12.55 17.73L16 29.55z"] {
    fill: #e38bb3 !important;
  }

  /* 공유/더보기 버튼 */
  button[aria-label*="share"],
  button[aria-label*="menu"],
  button svg[aria-hidden="true"] {
    background-color: #ead1dc !important;
    border-radius: 8px !important;
    padding: 4px !important;
  }

  /* 프로필 이미지 */
  img[alt*="avatar"],
  img[alt*="profile"] {
    border: 2px solid #e38bb3 !important;
    border-radius: 50% !important;
  }
}
